/* Filter Bar Styles */

.filter-bar {
  display: flex;
  align-items: center;
  gap: 17px;
  margin-bottom: 14px;
  width: 100%;
  flex-wrap: wrap;
}
.filter-bar label {
  font-weight: 500;
  color: var(--primary, #6C2EBE);
  margin-right: 7px;
}

/* Pill-button and modern look for selects and date inputs */
.filter-bar select,
.filter-bar input[type="date"] {
  font-size: 1em;
  padding: 7px 14px;
  border-radius: 15px;
  border: 1.6px solid var(--border-color, #ede3ff);
  background: var(--surface, #faf8ff);
  color: #23243A;
  margin-right: 2px;
  box-shadow: 0 1.5px 7px rgba(108,46,190,0.04);
  outline: none;
  transition: border 0.16s, box-shadow 0.18s;
}
.filter-bar select:focus,
.filter-bar input[type="date"]:focus {
  border: 1.6px solid var(--primary, #6C2EBE);
  background: #f3f0fa;
  box-shadow: 0 2.5px 12px rgba(108,46,190,0.10);
}
.filter-bar select:hover,
.filter-bar input[type="date"]:hover {
  border: 1.8px solid var(--accent, #6C2EBE);
}
.filter-bar option {
  color: #39336A;
}

@media (max-width: 800px) {
  .filter-bar {
    flex-wrap: wrap;
    gap: 11px;
    padding: 0 0;
    width: 100%;
  }
}
@media (max-width: 650px) {
  .filter-bar {
    flex-direction: column;
    align-items: flex-start;
    gap: 9px;
    width: 100%;
    padding: 0;
  }
  .filter-bar select, .filter-bar input[type="date"] {
    width: 100%;
    box-sizing: border-box;
  }
